corrected_code:
const express = require('express');
const Agenda = require('agenda');
const { ObjectId } = require('mongodb');
const { authSession } = require('../auth');

const router = express.Router();
const agenda = new Agenda({ db: { address: process.env.MONGO_URI } });

router.post('/api/agenda/jobs/:jobId/now', authSession, async (req, res) => {
  const jobs = await agenda.jobs({
    _id: new ObjectId(req.params.jobId),
    'data.creatorId': req.user.id,
  });
  if (!jobs.length) {
    return res.status(403).json({ error: 'Forbidden: job not found or unauthorized' });
  }

  const job = jobs[0];
  await job.run();
  res.json({ status: 'executed', jobId: req.params.jobId });
});
